'use strict';
const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const keys=['zone','tolerance','atr_mult','custom_floor','touch','min_touch','gap','side','confirm','confirm_pct','confirm_bars','timeout','fee_bps','spread_bps','objective','min_period','max_period','step','horizon','visual_weight','train','start','end','timeframe'];
let specs=[{type:'EMA',period:21,color:'#64e1be',width:2},{type:'SMA',period:55,color:'#f6c768',width:2},{type:'EMA',period:100,color:'#95aaff',width:2}],data=null,last=null,auto=null,ready=false,busy=false,seq=0,timer=null,cache={},revision=0;
const pending=new Map(),worker=new Worker('worker.js');
function status(s,error=false){$('status').textContent=s;$('status').classList.toggle('error',error)}
worker.onmessage=({data:m})=>{if(m.ready){ready=true;$('optimize').disabled=false;status('Pythoni arvutuskeskkond on valmis.');update();return;}if(pending.has(m.id)){let p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(Error(m.error)):p.resolve(m.result)}else if(m.error)status(m.error,true)};
worker.onerror=e=>status('Pythoni laadimine ebaõnnestus. Kontrolli internetiühendust ja CDN-i ligipääsu. '+e.message,true);
function rpc(payload){return new Promise((resolve,reject)=>{let id=++seq;pending.set(id,{resolve,reject});worker.postMessage({id,payload})})}
function params(){let p={};keys.forEach(k=>p[k]=$(k).value);return p}
function snapshot(){return {schema_version:'1.0',symbol:$('symbol').value.toUpperCase().trim(),params:params(),specs:structuredClone(specs),range:$('range').value,zones:$('zones').checked}}
function syncDates(){if(!data)return;if($('range').value==='custom')return;let end=new Date(data.prices.at(-1).date+'T12:00:00Z');let start=new Date(end);start.setUTCMonth(start.getUTCMonth()-Number($('range').value));$('end').value=end.toISOString().slice(0,10);$('start').value=start.toISOString().slice(0,10)}
async function getData(symbol){if(cache[symbol])return cache[symbol];let r=await fetch('data/'+encodeURIComponent(symbol)+'.json');if(!r.ok)throw Error(symbol+' pole andmepaketis. Impordi selle sümboli CSV / JSON või käivita update_data.py --symbols '+symbol);let d=await r.json();if(!d.prices?.length)throw Error('Hinnaandmed puuduvad');cache[symbol]=d;return d}
async function load(){try{const symbol=$('symbol').value.trim().toUpperCase();if(!/^[A-Z0-9^][A-Z0-9.^-]{0,14}$/.test(symbol))throw Error('Kontrolli sümbolit');status('Laadin '+symbol+' andmeid…');data=await getData(symbol);$('symbol').value=symbol;syncDates();await update()}catch(e){status(e.message,true)}}
function renderRows(){const root=$('maRows');root.innerHTML='';specs.forEach((s,i)=>{const row=document.createElement('div');row.className='marow';row.innerHTML=`<select aria-label="Keskmise tüüp">${['SMA','EMA','WMA'].map(t=>`<option ${s.type===t?'selected':''}>${t}</option>`).join('')}</select><input aria-label="Periood" type="number" min="1" max="500" value="${s.period}"><input aria-label="Joone värv" type="color" value="${esc(s.color)}"><input aria-label="Joone paksus" type="number" min="1" max="6" value="${s.width}"><button aria-label="Eemalda keskmine">×</button>`;const fields=row.querySelectorAll('input,select');fields.forEach((el,j)=>el.onchange=()=>{const k=['type','period','color','width'][j];s[k]=j===1||j===3?Number(el.value):el.value;schedule()});row.querySelector('button').onclick=()=>{if(specs.length>1){specs.splice(i,1);renderRows();schedule()}};root.append(row)})}
function schedule(){if(auto)$('ranking').classList.add('stale');revision++;clearTimeout(timer);timer=setTimeout(()=>update(),250)}
async function update(action='analyze'){if(!ready||!data)return;if(busy){if(action==='analyze')schedule();return}busy=true;$('optimize').disabled=true;const rev=revision;status(action==='optimize'?'Otsin SMA, EMA ja WMA kandidaate ainult treeningandmetel…':'Arvutan puuteid ja signaale…');try{const snap=snapshot();if(snap.specs.some(s=>!Number.isInteger(s.period)||s.period<1||s.period>500||s.width<1||s.width>6))throw Error('Periood peab olema täisarv 1–500 ja joone paksus 1–6.');let r=await rpc({action,prices:data.prices,symbol:data.symbol,source:data.source,params:snap.params,specs:snap.specs});if(rev!==revision){return}last=r;if(action==='optimize'){auto={...snap,params:r.params,specs:r.ranking.slice(0,2).map((x,i)=>({...x.spec,color:i?'#f6c768':'#64e1be'}))};renderRanking(r.ranking);status('Otsing valmis. TOP 5 leiti treeningandmetel; testitulemused on eraldi.')}else status('Valmis · '+data.symbol+' · viimane hinnapäev '+data.prices.at(-1).date);draw(r);renderStatsOptions(r)}catch(e){status(e.message,true)}finally{busy=false;$('optimize').disabled=!ready}}
const baseLayout={paper_bgcolor:'#131c26',plot_bgcolor:'#131c26',font:{color:'#91a1b2',family:'DM Sans',size:11},margin:{l:18,r:65,t:20,b:40},legend:{orientation:'h',y:1.1},xaxis:{gridcolor:'#25313d',rangeslider:{visible:false}},yaxis:{gridcolor:'#25313d',side:'right',tickprefix:'$'},hovermode:'x unified',dragmode:'zoom'};
function chartPrices(prices){if($('timeframe').value==='daily')return prices;let map=new Map();for(let r of prices){let d=new Date(r.date+'T12:00Z');let delta=(5-d.getUTCDay()+7)%7;d.setUTCDate(d.getUTCDate()+delta);let key=d.toISOString().slice(0,10),v=map.get(key);if(!v)map.set(key,{...r,date:key});else{v.high=Math.max(v.high,r.high);v.low=Math.min(v.low,r.low);v.close=r.close;v.volume+=r.volume}}return [...map.values()]}
function draw(r){if(typeof Plotly==='undefined'){status('Graafikuteek ei laadinud. Kontrolli CDN-i ühendust.',true);return}let bars=chartPrices(r.prices), traces=[{type:'candlestick',name:r.symbol,x:bars.map(x=>x.date),open:bars.map(x=>x.open),high:bars.map(x=>x.high),low:bars.map(x=>x.low),close:bars.map(x=>x.close),increasing:{line:{color:'#74b7a4',width:1}},decreasing:{line:{color:'#617487',width:1}}}];for(let a of r.results){let s=a.spec,color=s.color||'#64e1be';if($('zones').checked){traces.push({x:r.dates,y:a.lower,type:'scatter',mode:'lines',line:{width:0},hoverinfo:'skip',showlegend:false});traces.push({x:r.dates,y:a.upper,type:'scatter',mode:'lines',line:{width:0},fill:'tonexty',fillcolor:color+'12',hoverinfo:'skip',showlegend:false})}traces.push({x:r.dates,y:a.ma,type:'scatter',mode:'lines',name:s.type+' '+s.period,line:{color,width:s.width||2}});let byDate=new Map(r.prices.map(p=>[p.date,p]));traces.push({x:a.touches.map(t=>t.date),y:a.touches.map(t=>byDate.get(t.date).close),type:'scatter',mode:'markers',name:s.type+' '+s.period+' puuted',showlegend:false,marker:{symbol:'diamond-open',size:8,color}});for(let direction of [1,-1]){let ss=a.signals.filter(t=>t.direction===direction);traces.push({x:ss.map(t=>t.date),y:ss.map(t=>byDate.get(t.date).close),text:ss.map(t=>t.reason),hovertemplate:'%{text}<extra></extra>',type:'scatter',mode:'markers',showlegend:false,marker:{symbol:direction>0?'triangle-up':'triangle-down',size:10,color:direction>0?'#64e1be':'#ff91ab'}})}}Plotly.react('chart',traces,{...baseLayout,uirevision:r.symbol+r.params.start+r.params.end+r.params.timeframe,shapes:[{type:'rect',xref:'x',yref:'paper',x0:r.split_date,x1:r.dates.at(-1),y0:0,y1:1,fillcolor:'#3d918d',opacity:.07,line:{width:0}}],annotations:[{xref:'x',yref:'paper',x:r.split_date,y:1,text:'TEST →',showarrow:false,font:{color:'#64e1be',size:10}}]},{responsive:true,displaylogo:false});$('chartTitle').textContent=r.symbol+' · Hind ja libisevad keskmised';$('source').textContent=(r.source.provider||'Kasutaja import')+' · '+(r.source.adjustment||'Korrigeerimine pole kinnitatud')+' · viimane '+data.prices.at(-1).date;}
let statResults=[];
function renderStatsOptions(r){statResults=r.results;const old=$('statMA').value;$('statMA').innerHTML=r.results.map((x,i)=>`<option value="${i}">${esc(x.spec.type)} ${x.spec.period}</option>`).join('');if(Number(old)<r.results.length)$('statMA').value=old;renderStats()}
const fmt=x=>x==null?'—':Number(x).toFixed(2)+'%';
function renderStats(){let a=statResults[Number($('statMA').value)||0];if(!a)return;const h=String($('horizon').value),tr=a.train[h],te=a.test[h];$('warning').textContent=te.n<10?'Väike testvalim: alla 10 sõltumatu tehingu. Järeldused on ebakindlad.':(tr.mean>0&&te.mean<=0?'Treeningtulemus on positiivne, testtulemus mitte. Võimalik üleoptimeerimine.':'Testperiood on otsingust eraldatud. Korduv parameetrite valimine testi järgi vähendab selle sõltumatust.');$('metrics').innerHTML=`<div class="metric"><span>TREENINGU PUUTEID</span><strong>${a.touch_count}</strong></div><div class="metric"><span>TESTI KESKMINE · ${h} PÄEVA</span><strong class="${te.mean>0?'pos':'neg'}">${fmt(te.mean)}</strong></div><div class="metric"><span>TESTI TEHINGUID</span><strong>${te.n}</strong></div>`;$('stats').innerHTML=[5,10,20,40,60].map(n=>['train','test'].map(part=>{let s=a[part][n];return `<tr class="${part==='test'?'test':''}"><td>${n} päeva</td><td>${part==='train'?'Treening':'Test'}</td><td>${s.n} / ${s.eligible}</td><td class="${s.mean>0?'pos':'neg'}">${fmt(s.mean)}</td><td>${fmt(s.median)}</td><td title="Wilsoni 95% vahemik: ${fmt(s.win_ci[0])} – ${fmt(s.win_ci[1])}">${fmt(s.win_rate)}</td><td>${fmt(s.mae)}</td><td>${fmt(s.buy_hold)}</td></tr>`}).join('')).join('');$('signals').innerHTML='<table><tr><th>Kuupäev</th><th>Signaal</th></tr>'+a.signals.map(s=>`<tr><td>${s.date}</td><td>${esc(s.reason)}</td></tr>`).join('')+'</table>'}
function renderRanking(list){$('ranking').classList.remove('stale');$('ranking').innerHTML='<div class="tablewrap"><table><tr><th>Koht</th><th>Keskmine</th><th>Skoor</th><th>Treening</th><th>Test</th><th></th></tr>'+list.map((r,i)=>`<tr><td>0${i+1}</td><td>${r.spec.type} ${r.spec.period}</td><td>${r.score.toFixed(1)}</td><td>${fmt(r.train[$('horizon').value].mean)}</td><td>${fmt(r.test[$('horizon').value].mean)}</td><td><button class="rankpick" data-rank="${i}">Lisa graafikule</button></td></tr>`).join('')+'</table></div>';$('ranking').querySelectorAll('button').forEach(b=>b.onclick=()=>{if(specs.length>=12){status('Korraga saab kuvada kuni 12 keskmist.',true);return}specs.push({...list[Number(b.dataset.rank)].spec,color:['#f6c768','#ff91ab','#9eabff','#53b7ee','#e7a6f2'][Number(b.dataset.rank)]});renderRows();schedule()})}
function download(name,obj){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function applySettings(s){if(s.schema_version!=='1.0'||!s.params||!Array.isArray(s.specs)||s.specs.length<1||s.specs.length>12)throw Error('Vigane seadistusfail');for(const x of s.specs){if(!['SMA','EMA','WMA'].includes(x.type)||!Number.isInteger(Number(x.period))||x.period<1||x.period>500||!/^#[0-9a-f]{6}$/i.test(x.color)||x.width<1||x.width>6)throw Error('Vigane keskmise seadistus')}let next=await getData(s.symbol);data=next;$('symbol').value=s.symbol;keys.forEach(k=>{if(s.params[k]!=null)$(k).value=s.params[k]});$('range').value=s.range||'custom';$('zones').checked=s.zones??true;specs=structuredClone(s.specs);renderRows();await update()}
$('load').onclick=load;$('symbol').onkeydown=e=>{if(e.key==='Enter')load()};$('preset').onchange=()=>{$('symbol').value=$('preset').value;load()};$('range').onchange=()=>{syncDates();schedule()};keys.forEach(k=>$(k).onchange=()=>{if(k==='start'||k==='end')$('range').value='custom';schedule()});$('zones').onchange=()=>{if(last)draw(last)};$('addMA').onclick=()=>{if(specs.length<12){specs.push({type:'WMA',period:34,color:'#eea0c1',width:2});renderRows();schedule()}};$('optimize').onclick=()=>update('optimize');$('compare').onclick=()=>update();$('statMA').onchange=renderStats;
$('restore').onclick=()=>{if(!auto){status('Käivita esmalt automaatne otsing.',true);return}applySettings(auto).catch(e=>status(e.message,true))};$('save').onclick=()=>{try{localStorage.setItem('ma-settings-v1',JSON.stringify(snapshot()));status('Seadistus salvestatud sellesse brauserisse.')}catch(e){status(e.message,true)}};$('loadSaved').onclick=()=>{try{const s=localStorage.getItem('ma-settings-v1');if(!s)throw Error('Salvestatud seadistus puudub');applySettings(JSON.parse(s)).catch(e=>status(e.message,true))}catch(e){status(e.message,true)}};$('exportSettings').onclick=()=>download('ma-settings.json',snapshot());$('exportResults').onclick=()=>{if(last)download('ma-results-'+last.symbol+'.json',{...last,last_automatic_settings:auto});else status('Käivita esmalt analüüs.',true)};$('settingsFile').onchange=async e=>{try{await applySettings(JSON.parse(await e.target.files[0].text()))}catch(x){status(x.message,true)}e.target.value=''};
$('pricesFile').onchange=async e=>{try{let f=e.target.files[0],txt=await f.text(),d;if(f.name.endsWith('.json'))d=JSON.parse(txt);else{if(!window.Papa)throw Error('CSV lugeja ei laadinud');let parsed=Papa.parse(txt,{header:true,skipEmptyLines:true,transformHeader:h=>h.toLowerCase().trim()});if(parsed.errors.length)throw Error(parsed.errors[0].message);d={symbol:$('symbol').value.toUpperCase().trim(),source:{provider:'Kasutaja CSV: '+f.name,updated_at:new Date().toISOString(),adjustment:'Kasutaja vastutab korrigeerimise eest'},prices:parsed.data}}if(!d.prices?.length)throw Error('Hinnad puuduvad');if(!ready)throw Error('Oota Pythoni käivitumist');await rpc({prices:d.prices,params:{},specs:[specs[0]]});data=d;cache[d.symbol]=d;$('symbol').value=d.symbol;syncDates();if(![...$('stockChoices').querySelectorAll('input')].some(x=>x.value===d.symbol)){let label=document.createElement('label');label.className='check';let box=document.createElement('input');box.type='checkbox';box.value=d.symbol;box.checked=true;label.append(box,document.createTextNode(d.symbol));$('stockChoices').append(label)}await update()}catch(x){status(x.message,true)}e.target.value=''};
$('compareStocks').onclick=async()=>{try{const symbols=[...$('stockChoices').querySelectorAll('input:checked')].map(x=>x.value);if(symbols.length<2)throw Error('Vali vähemalt kaks aktsiat');const ds=await Promise.all(symbols.map(getData)),start=$('start').value,end=$('end').value;const sets=ds.map(d=>new Set(d.prices.filter(p=>p.date>=start&&p.date<=end).map(p=>p.date)));const dates=[...sets[0]].filter(d=>sets.every(s=>s.has(d))).sort();if(dates.length<2)throw Error('Ühist ajavahemikku pole');let traces=ds.map(d=>{let map=new Map(d.prices.map(p=>[p.date,Number(p.close)])),base=map.get(dates[0]);return {x:dates,y:dates.map(date=>100*map.get(date)/base),name:d.symbol,type:'scatter',mode:'lines'}});Plotly.react('stockChart',traces,{...baseLayout,height:290,yaxis:{gridcolor:'#25313d',title:'Algväärtus = 100'}},{responsive:true,displaylogo:false});status('Aktsiate võrdlus valmis.')}catch(e){status(e.message,true)}};
renderRows();load();
